{
  "name": "jira-cli-agent",
  "version": "0.2.3",
  "description": "Jira Cloud for AI coding agents: gives OpenCode the jira-cli MCP server and the jira-ticket skill, and Pi the jira-ticket skill. Unofficial; not affiliated with Atlassian.",
  "license": "MIT",
  "repository": { "type": "git", "url": "git+https://github.com/ejklock/jira-cli.git", "directory": "packages/jira-cli-agent" },
  "homepage": "https://github.com/ejklock/jira-cli#readme",
  "type": "module",
  "main": "./index.ts",
  "exports": {
    ".": "./index.ts",
    "./server": "./index.ts"
  },
  "keywords": ["pi-package", "opencode", "opencode-plugin", "jira", "mcp", "model-context-protocol", "ai-agent", "skill", "issue-tracking"],
  "pi": { "skills": ["skills"] },
  "scripts": {
    "test": "node --test"
  },
  "files": ["index.ts", "skills", "README.md"]
}

import { fileURLToPath } from "node:url"

type McpEntry = { type: "local"; command: string[] } & Record<string, unknown>
type OpencodeConfig = {
  mcp?: Record<string, McpEntry>
  skills?: { paths?: string[] }
}

const skillsDir = fileURLToPath(new URL("./skills", import.meta.url))

// OpenCode 1.19 can register an MCP server and a skills directory only by
// mutating the merged config in the `config` hook. A user's own
// `jira-cli` entry wins over the default, and the skills directory is
// listed once however often the hook runs.
export const server = async () => ({
  config: async (config: OpencodeConfig): Promise<void> => {
    config.mcp = { "jira-cli": { type: "local", command: ["jira", "mcp"] }, ...config.mcp }
    const paths = config.skills?.paths ?? []
    config.skills = { ...config.skills, paths: paths.includes(skillsDir) ? paths : [...paths, skillsDir] }
  },
})
